CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NULL, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) UNIQUE NOT NULL, base_path TEXT NOT NULL, created_at DATETIME NULL, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, server_user_id BIGINT UNSIGNED NULL, name VARCHAR(255) NOT NULL, path VARCHAR(768) UNIQUE NOT NULL, type VARCHAR(64) NOT NULL DEFAULT 'unknown', cms_type VARCHAR(64) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, last_scan_at DATETIME NULL, created_at DATETIME NULL, updated_at DATETIME NULL, INDEX sites_server_user_id_idx(server_user_id), CONSTRAINT sites_user_fk FOREIGN KEY(server_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS scan_runs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, started_at DATETIME NOT NULL, finished_at DATETIME NULL, status VARCHAR(32) NOT NULL DEFAULT 'running', scope_type VARCHAR(32) NOT NULL DEFAULT 'full', scope_value TEXT NULL, files_scanned BIGINT NOT NULL DEFAULT 0, findings_count BIGINT NOT NULL DEFAULT 0, error_text TEXT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, INDEX scan_runs_status_idx(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_snapshots (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, site_id BIGINT UNSIGNED NULL, path VARCHAR(768) NOT NULL, relative_path TEXT NULL, owner VARCHAR(255) NULL, `group` VARCHAR(255) NULL, permissions VARCHAR(16) NULL, size BIGINT NOT NULL DEFAULT 0, mtime DATETIME NULL, sha256 CHAR(64) NULL, first_seen_at DATETIME NOT NULL, last_seen_at DATETIME NOT NULL, last_changed_at DATETIME NULL, is_missing TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NULL, updated_at DATETIME NULL, UNIQUE KEY file_snapshots_path_unique(path), INDEX file_snapshots_site_id_idx(site_id), INDEX file_snapshots_sha256_idx(sha256), CONSTRAINT snapshots_site_fk FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS findings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, scan_run_id BIGINT UNSIGNED NULL, site_id BIGINT UNSIGNED NULL, path VARCHAR(768) NOT NULL, risk VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'new', type VARCHAR(64) NOT NULL DEFAULT 'unknown', rule_key VARCHAR(128) NULL, fingerprint CHAR(64) NULL, title VARCHAR(255) NOT NULL, description TEXT NULL, matched_rules LONGTEXT NULL, related_log_event_ids LONGTEXT NULL, sha256 CHAR(64) NULL, size BIGINT NULL, mtime DATETIME NULL, owner VARCHAR(255) NULL, permissions VARCHAR(16) NULL, first_seen_at DATETIME NULL, last_seen_at DATETIME NULL, created_at DATETIME NULL, updated_at DATETIME NULL, INDEX findings_path_idx(path), INDEX findings_status_idx(status), INDEX findings_risk_idx(risk), INDEX findings_site_id_idx(site_id), INDEX findings_fingerprint_idx(path,type,fingerprint,status), INDEX findings_scan_run_id_idx(scan_run_id), CONSTRAINT findings_scan_fk FOREIGN KEY(scan_run_id) REFERENCES scan_runs(id) ON DELETE SET NULL, CONSTRAINT findings_site_fk FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS log_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, site_id BIGINT UNSIGNED NULL, log_path TEXT NOT NULL, line_number BIGINT NULL, ip VARCHAR(64) NULL, method VARCHAR(16) NULL, uri VARCHAR(768) NULL, status_code INT NULL, user_agent TEXT NULL, referer TEXT NULL, event_type VARCHAR(128) NOT NULL, risk VARCHAR(32) NOT NULL, raw_line LONGTEXT NOT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, INDEX log_events_site_id_idx(site_id), INDEX log_events_uri_idx(uri), INDEX log_events_ip_idx(ip), CONSTRAINT log_events_site_fk FOREIGN KEY(site_id) REFERENCES sites(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS quarantine_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, finding_id BIGINT UNSIGNED NULL, original_path VARCHAR(768) NOT NULL, quarantine_path TEXT NOT NULL, sha256 CHAR(64) NULL, owner VARCHAR(255) NULL, `group` VARCHAR(255) NULL, permissions VARCHAR(16) NULL, mtime DATETIME NULL, reason TEXT NULL, status VARCHAR(32) NOT NULL DEFAULT 'quarantined', created_at DATETIME NULL, updated_at DATETIME NULL, INDEX quarantine_items_original_path_idx(original_path), INDEX quarantine_items_finding_id_idx(finding_id), CONSTRAINT quarantine_finding_fk FOREIGN KEY(finding_id) REFERENCES findings(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, description TEXT NULL, risk VARCHAR(32) NOT NULL, type VARCHAR(64) NOT NULL, pattern TEXT NOT NULL, pattern_type VARCHAR(32) NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NULL, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS allowlist_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, path_pattern TEXT NULL, sha256 CHAR(64) NULL, reason TEXT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NULL, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `key` VARCHAR(255) UNIQUE NOT NULL, value TEXT NULL, created_at DATETIME NULL, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ai_analyses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, finding_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(64) NULL, model VARCHAR(128) NULL, risk VARCHAR(32) NULL, confidence DOUBLE NULL, summary TEXT NULL, raw_response LONGTEXT NULL, created_at DATETIME NULL, updated_at DATETIME NULL, INDEX ai_analyses_finding_id_idx(finding_id), CONSTRAINT ai_finding_fk FOREIGN KEY(finding_id) REFERENCES findings(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
